import './App.css';
import { Navbar } from './Components/Navbar/Navbar';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';

import Shop from './Pages/Shop';
import ShopCategory from './Pages/ShopCategory';
import Product from './Pages/Product';
import Cart from './Pages/Cart';
import LoginSignup from './Pages/LoginSignup';
import Footer from './Components/Footer/Footer';

import men_banner from './Components/Assets/men_banner.png';
import women_banner from './Components/Assets/women_banner.png';
import kid_banner from './Components/Assets/kids_banner.png';


// Protected Route
function ProtectedRoute({ children }) {
  const isLoggedIn = localStorage.getItem('isLoggedIn');

  return isLoggedIn ? children : <Navigate to="/login" />;
}


function App() {
  return (
    <BrowserRouter>

      <Navbar />

      <Routes>
        <Route path="/login" element={<LoginSignup />} />
        <Route path="/" element={<ProtectedRoute><Shop /></ProtectedRoute>}/>
        <Route path="/mens" element={<ProtectedRoute><ShopCategory banner={men_banner} category="men" /></ProtectedRoute>}/>
        <Route path="/womens" element={
            <ProtectedRoute>
              <ShopCategory banner={women_banner} category="women" />
            </ProtectedRoute>
          }
        />


        {/* Kids Page - Login Required */}
        <Route
          path="/kids"
          element={
            <ProtectedRoute>
              <ShopCategory banner={kid_banner} category="kid" />
            </ProtectedRoute>
          }
        />


        {/* Product Page - Login Required */}
        <Route
          path="/product/:productId"
          element={
            <ProtectedRoute>
              <Product />
            </ProtectedRoute>
          }
        />


        {/* Cart Page - Login Required */}
        <Route
          path="/cart"
          element={
            <ProtectedRoute>
              <Cart />
            </ProtectedRoute>
          }
        />

      </Routes>

      <Footer />

    </BrowserRouter>
  );
}

export default App;
